localparam int bitmax=31;
typedef logic [bitmax:0] data_type;

logic [3:0] data;
logic valid;
logic ready;

modport rtl_receive(input data, valid, output ready),
rtl_send (output data, valid, input ready);

task write(input data_type d);
@(posedge clk) ;
while (ready !== 1) @(posedge clk) ;
data = d;
$display("in write task, data is %0h", data);
valid = 1;
@(posedge clk) data = 'x;
valid = 0;

task read(output data_type d);
ready = 1;
while (valid !== 1) @(negedge clk) ;
ready = 0;
d = data;
@(negedge clk) ;

endinterface

logic data;
logic valid; //
logic ready; //

modport rtl_receive(input data, valid, output ready),
rtl_send (output data, valid, input ready);

task write(input data_type d);
@(posedge clk) ;
while (ready !== 1) @(posedge clk) ;
for (int i = 0; i <= bitmax; i++)
data = d[i];
valid = 1;
@(posedge clk) data = 'x;
end
valid = 0;

task read(output data_type d);
ready = 1;
while (valid !== 1) @(negedge clk) ;
ready = 0;
for (int i = 0; i <= bitmax; i++)
d[i] = data;
@(negedge clk) ;
end

-postUnrRun "source user.tcl"
//where user.tcl is a user created a tcl script

-postUnrRun "exec user.proc"
//where user.proc is a tcl proc created by user

constant VAL0 : bit_vector(BITS-1 downto 0) := (BITS-1 => '1', others
=> '0');
constant VAL1 : bit_vector(8-1 downto 0) := (8-1 => '1', others =>
'0');
assert VAL0=VAL1 report "wrong aggregate" severity error;

