The following is an example of this feature:
Example 103 test.sv

rand int i;
packet pkt = new;
weak_reference#(packet) weak_obj;
weak_obj = new(pkt);
#1;
$display("weak_obj get = %p", weak_obj.get());
#1;
$display("weak_obj get = %p", weak_obj.get_id(pkt));
#1;
weak_obj.clear();
$display("weak_obj get = %p", weak_obj.get());
end

