logic valid[2];

module tb_top;
simple_if phy_if();
virtual simple_if virt_inst[2];

cls c = new;
phy_if.valid[0] = 1'b0;
virt_inst[0] = phy_if;
c.touch_task(tb_top.virt_inst[0].valid[0]);
end
always @(virt_inst[0].valid[0]) begin
end
assert(count == 1) $display ("Passed!");

else $display ("Failed!");
end
No compile-time error.
Runtime result:
Passed!
