x dist {default :/ c, [1:202] := 2};
x dist {default :/ d, [100:402] := 3};
// std::randomize with expressions
std::randomize(k) with {
k.x dist { default :/ (k.b + k.c + k.d), [10:102] := 1 };
k.x dist { default :/ k.c, [1:202] := 2 };
k.x dist { default :/ k.d, [100:402] := 3 };
};
Enums and packed structs
