always #5 clk = ~clk; //clock generation
always #5 clk1 = ~clk1; //clock generation
always #5 clk2 = ~clk2; //clock generation
a=0; b=1;
#30 a = 1;
#30 a = 0;
#30 a =1;
#100
End
