int vc_isVector(vc_handle)
This routine returns a 1 value if the vc_handle is to a vector reg or bit. It returns a 0
value for a vector bit or reg or any memory. For example, using the Verilog code from the
previous example, and the following C/C++ function:
scalarfinder(vc_handle h1, vc_handle h2, vc_handle h3, vc_handle h4)
{
int i1 = vc_isVector(h1),
i2 = vc_isVector(h2),

i3 = vc_isVector(h3),
i4 = vc_isVector(h4);
printf("\ni1=%d i2=%d i3=%d i4=%d\n\n",i1,i2,i3,i4);
}
The function displays the following:
i1=0 i2=1 i3=0 i4=0
int vc_isMemory(vc_handle)
This routine returns a 1 value if the vc_handle is to a memory. It returns a 0 value for a
bit or reg that is not a memory. For example, using the Verilog code from the previous
example and the following C/C++ function:

scalarfinder(vc_handle h1, vc_handle h2, vc_handle h3, vc_handle h4)
{
int i1 = vc_isMemory(h1),
i2 = vc_isMemory(h2),
i3 = vc_isMemory(h3),
i4 = vc_isMemory(h4);
printf("\ni1=%d i2=%d i3=%d i4=%d\n\n",i1,i2,i3,i4);
}
The function displays the following:
i1=0 i2=0 i3=1 i4=1
int vc_is4state(vc_handle)
This routine returns a 1 value if the vc_handle is to a reg or memory that simulates with
four states. It returns a 0 value for a bit or a memory that simulates with two states. For
example, the following Verilog code uses metacomments to specify four- and two-state
simulation:
extern void statefinder (input reg r1,
input reg [1:0] r2,
input reg [1:0] array [1:0] r3,
input reg array [1:0] r4,
input bit r5,
input bit [1:0] r6,
input bit [1:0] array [1:0] r7,
input bit array [1:0] r8);
reg /*4value*/ r1;
reg /*4value*/ [1:0] r2;
reg /*4value*/ [1:0] r3 [1:0];
reg /*4value*/ r4 [1:0];
reg /*2value*/ r5;
reg /*2value*/ [1:0] r6;

reg /*2value*/ [1:0] r7 [1:0];
reg /*2value*/ r8 [1:0];
statefinder(r1,r2,r3,r4,r5,r6,r7,r8);
The C/C++ function that calls the vc_is4state routine is as follows:

statefinder(vc_handle h1, vc_handle h2, vc_handle h3,
vc_handle h4,vc_handle h5, vc_handle h6,
vc_handle h7, vc_handle h8)
{
printf("\nThe vc_handles to 4state are:");
printf("\nh1=%d h2=%d h3=%d h4=%d\n\n",
vc_is4state(h1),vc_is4state(h2),
vc_is4state(h3),vc_is4state(h4));
printf("\nThe vc_handles to 2state are:");
printf("\nh5=%d h6=%d h7=%d h8=%d\n\n",
vc_is4state(h5),vc_is4state(h6),
vc_is4state(h7),vc_is4state(h8));
}
The function prints the following:
The vc_handles to 4state are:
h1=1 h2=1 h3=1 h4=1

The vc_handles to 2state are:
h5=0 h6=0 h7=0 h8=0
int vc_is2state(vc_handle)
This routine does the opposite of the vc_is4state routine. For example, using the Verilog
code from the previous example and the following C/C++ function:

statefinder(vc_handle h1, vc_handle h2, vc_handle h3,
vc_handle h4, vc_handle h5, vc_handle h6,
vc_handle h7, vc_handle h8)
{
printf("\nThe vc_handles to 4state are:");
printf("\nh1=%d h2=%d h3=%d h4=%d\n\n",
vc_is2state(h1),vc_is2state(h2),
vc_is2state(h3),vc_is2state(h4));
printf("\nThe vc_handles to 2state are:");
printf("\nh5=%d h6=%d h7=%d h8=%d\n\n",
vc_is2state(h5),vc_is2state(h6),

vc_is2state(h7),vc_is2state(h8));
}
The function displays the following:
The vc_handles to 4state are:
h1=0 h2=0 h3=0 h4=0

The vc_handles to 2state are:
h5=1 h6=1 h7=1 h8=1
int vc_is4stVector(vc_handle)
This routine returns a 1 value if the vc_handle is to a vector reg. It returns a 0 value if
the vc_handle is to a scalar reg, scalar or vector bit, or memory. For example, using the
Verilog code from the previous example, and the following C/C++ function:

statefinder(vc_handle h1, vc_handle h2,
vc_handle h3, vc_handle h4,
vc_handle h5, vc_handle h6,
vc_handle h7, vc_handle h8)
{
