module logic_to_real(output real realport, input logic logicport)
parameter Hi = 5;
parameter Low = 0;
parameter X = 2.5;
parameter Z = 3;
real treal;
assign real = treal;
always @(logicport) begin
if (logicport === 1'b1)
treal = Hi;
