reg [3:0] r1_sel;
reg rx_sel, ry_sel;
r1_sel = 0;
rx_sel = 0;
ry_sel = 0;
hst.ack = 0;

case (hst.adr)
0: begin
r1_sel = {2'b00, hst.sel[1:0]};
end
1: begin
r1_sel = {hst.sel[1:0], 2'b00};
end
2: begin
rx_sel = 1;
end
'h0100: begin
ry_sel = 1;
end
end

wire [31:0] r1_out;
ral_reg_r1_rtl r1(hst.clk, hst.rstn,
{hst.wdat[15:0], hst.wdat[15:0]},
r1_out, r1_sel, hst.wen,
usr.f10_out, usr.f10_rd, usr.f10_wr,
usr.f10_in, usr.f10_wen, usr.f11_in);

