hst.wdat[7:0], ry_out, ry_sel, hst.wen,
usr.ry_f20_sel, usr.ry_f20_wdat, usr.ry_f20_wen,
usr.ry_f20_rdat, usr.ry_f21_out, usr.ry_f21_rd,
usr.ry_f21_in, usr.ry_f21_wen, usr.ry_f22_sel,
usr.ry_f22_wdat, usr.ry_f22_wen, usr.ry_f22_rdat);

reg [15:0] _rdat;
_rdat = 16'b0;
unique casez ({|r1_sel[3:2], |r1_sel[1:0], |rx_sel, |ry_sel})
4'b1???: _rdat = r1_out[31:16];
4'b?1??: _rdat = r1_out[15:0];
4'b??1?: _rdat[7:0] = rx_out;
4'b???1: _rdat[7:0] = ry_out;
4'b0000: _rdat = 15'b0;

end

Memories
All memory instances are assumed to be external. For each memory instance, a set of
design-side signals is included in the block interface.
block b2 {
bytes 4;
register r1;
memory m1 @'h0100 {
bits 16;
size 256;
access rw;
}
memory m2 @'h1000 {
bits 23;
size 1k;
access ro;
}
}
interface ral_blk_b2_itf();

logic [7:0] f10_out;
logic f10_rd, f10_wr;
logic [7:0] f10_in;
logic f10_wen;
logic [7:0] f11_in;

logic [ 1:0] m1_sel;
logic [ 7:0] m1_adr;
logic [15:0] m1_rdat;
logic [15:0] m1_wdat;
logic m1_wen;

logic [ 2:0] m2_sel;
logic [ 9:0] m2_adr;
logic [22:0] m2_rdat;

modport regs(output f10_out, f10_rd, f10_wr,

input f10_in, f10_wen,
input f11_in,
output m1_sel, m1_adr, m1_wdat, m1_wen,
input m1_rdat,
output m2_sel, m2_adr,
input m2_rdat);

modport usr(input f10_out, f10_rd, f10_wr,
output f10_in, f10_wen,
output f11_in,
input m1_sel, m1_adr, m1_wdat, m1_wen,
output m1_rdat,
input m2_sel, m2_adr,
output m2_rdat);

reg [3:0] r1_sel;
reg [1:0] m1_sel;
reg [2:0] m2_sel;
r1_sel = 0;
m1_sel = 0;
m2_sel = 0;
hst.ack = 0;
case (hst.adr)
0: begin
r1_sel = hst.sel[3:0];
end
if (hst.adr >= 'h0100 && hst.adr <= 'h01FF) begin
m1_sel = hst.sel[1:0];
end
if (hst.adr >= 'h1000 && hst.adr <= 'h13FF) begin
m2_sel = hst.sel[2:0];
end
end

wire [31:0] r1_out;
ral_reg_r1_rtl r1(hst.clk, hst.rstn, hst.wdat[31:0],
r1_out, r1_sel, hst.wen,
usr.f10_out, usr.f10_rd, usr.f10_wr, usr.f10_in,
usr.f10_wen, usr.f11_in);

assign usr.m1_adr = hst.adr - 'h0100;
assign usr.m1_wdat = hst.wdat[15:0];

assign usr.m1_wen = hst.wen;

assign usr.m2_adr = hst.adr - 'h1000;

reg [31:0] _rdat;
unique casez ({|r1_sel, |m1_sel, |m2_sel})
3'b1??: _rdat = r1_out;
3'b?1?: _rdat[15:0] = usr.m1_rdat;
3'b??1: _rdat[21:0] = usr.m2_rdat;
3'b000: _rdat = 32'b0;
end

Shared memories are generated in an identical fashion: the sharing is implemented in the
block RTL code.
Multiple Domains
The arbitration between different physical interfaces for different domains is handled by the
generated RTL code for the multi-domain block. All domains are assumed to conform to
the host-side protocol and are synchronized to the same clock. For each domain, a host-
side slave interface is included in the block module pins.
When multiple domains attempt to write a shared register during the same cycle, the
domain declared first has priority.
register r4 {
field f1 {bits 8; access ro};
}

register r5 {
field f2 {bits 8; access rw};
shared;
}
block b3 {
domain north {
register r4=r1;
register r5=r2;

}
domain south {
register r4=r3;
register r5=r2;
}
}
module ral_blk_b3_rtl(vmm_ral_host_itf.slave north,
vmm_ral_host_itf.slave south,
ral_blk_b3_itf.regs usr);

reg r1_sel;
reg north_r2_sel;
reg south_r2_sel;
reg [7:0] r2_in;
reg r2_wen;
reg r3_sel;
r1_sel = 'b0;
north_r2_sel = 'b0;
south_r2_sel = 'b0;
r2_in = 'bx;
r2_wen = 'b0;
r3_sel = 'b0;
north.ack = 0;
south.ack = 0;

case (south.adr)
0: begin
r3_sel = south.sel[0];
south.ack = south.wen;
end
1: begin
south_r2_sel = south.sel[0];
r2_in = south.wdat[7:0];
r2_wen = south.wen;
south.ack = south.wen;
end
case (north.adr)
0: begin
r1_sel = north.sel[0];
north.ack = north.wen;
end
1: begin
north_r2_sel = north.sel[0];
if (north.wen) begin
if (r2_wen) south.ack = 0;
r2_wen = 1;

r2_in = north.wdat[7:0];
north.ack = 1;
end
end
end

wire [7:0] r1_out;
ral_reg_r4_rtl r1(north.clk, north.rstn,
north.wdat[7:0], r1_out, r1_sel, north.wen,
usr.r1_f1_in);

wire [7:0] r2_out;
wire r2_sel = north_r2_sel | south_r2_sel;
ral_reg_r5_rtl r2(north.clk, north.rstn,
r2_in, r2_out, r2_sel, r2_wen,
usr.f2_out, usr.f2_rd, usr.f2_wr, usr.f2_in,
usr.f2_wen);

wire [7:0] r3_out;

ral_reg_r4_rtl r3(south.clk, south.rstn,
south.wdat[7:0], r3_out, r3_sel, south.wen,
usr.r3_f1_in);

reg [7:0] _north_rdat;
unique casez ({r1_sel, r2_sel})
2'b1?: _north_rdat = r1_out;
2'b?1: _north_rdat = r2_out;
2'b00: _north_rdat = 8'b0;
end
assign north.rdat[7:0] = _north_rdat;

reg [7:0] _south_rdat;
unique casez ({r1_sel, r2_sel})
2'b1?: _south_rdat = r3_out;
2'b?1: _south_rdat = r2_out;
2'b00: _south_rdat = 8'b0;
end
assign south.rdat[7:0] = _south_rdat;

Register Arrays
Register arrays present a challenge because they can easily create a large number of
fields. One possibility would be to flatten the register arrays, but this would create a large
number of signals in the block interface. Another approach would be to add an array offset
to the design-side interface and consider its value whenever a field in the register array
is read or written from the design. However, this would limit access to a single register in
the array per clock cycle and make it impossible to concurrently access different fields at
different offsets in the array.
Register arrays are implemented using generated instances of the individual register
modules and the corresponding design-side signals are provided as arrays.
block b4 {
register r4[256];
}
interface ral_blk_b4_itf();

logic [7:0] f1_in[256];

modport regs(input f1_in);

modport usr(output f1_in);

reg [7:0] _r4_sel_i;
reg r4_sel[256];
reg [31:0] i;
hst.ack = 0;
_r4_sel_i = 'bx;
for (i = 0; i < 256; i = i + 1) begin
r4_sel[i] = 'b0;
if (hst.adr == 0 + i*1) begin
r4_sel[i] = hst.sel[0];
_r4_sel_i = i;
end

end
end

wire [7:0] r4_out[256];
genvar _r4_i;
generate for (_r4_i=0; _r4_i<256; _r4_i=_r4_i+1)
begin: r4
ral_reg_r4_rtl i(hst.clk, hst.rstn, hst.wdat[7:0],
r4_out[_r4_i], r4_sel[_r4_i], hst.wen,
usr.f1_in[_r4_i]);
end
endgenerate

reg [7:0] _rdat;
begin: muxout
unique casez ({|r4_sel[_r4_sel_i]})
1'b1: _rdat = r4_out[_r4_sel_i];
1'b0: _rdat = 8'b0;
end
assign hst.rdat[7:0] = _rdat;

Register Files
For every regfile definition, a module is generated. The module is named according to
the unique scoped regfile type name and contains instances of the appropriate register
modules. A set of host-side slave interfaces is included in the module pins. A set of
design-side signals is included for each field in the register file.
The RTL generation template for a register file is:
module ral_rfile_<filename>_rtl(<host-side signals>,
{<design-side signals>});
<address decoding>
{<register module instantiations>}
<register muxing>
block b5 {
regfile rf {
register r4;
register r4=r5;

}
}
module ral_rfile_b5_rf_rtl(input clk,
input rstn,
input [`VMM_RAL_ADDR_WIDTH-1:0] hst_adr,
input [31:0] hst_wdat,
output logic [31:0] hst_rdat,
input [ 3:0] hst_sel,
input hst_wen,
output logic hst_ack,
input [ 7:0] r4_f1_in,
input [ 7:0] r5_f1_in);

reg r4_sel;
reg r5_sel;
r4_sel = 0;
r5_sel = 0;
hst_ack = 0;
case (hst_adr)
0: begin
r4_sel = hst_sel[0];
hst_ack = hst_wen;
end
1: begin
r5_sel = hst_sel[0];
hst_ack = hst_wen;
end
end

wire [7:0] r4_out;
ral_reg_r4_rtl r4(clk, rstn, hst_wdat[7:0],
r4_out, r4_sel, hst_wen,
r4_f1_in);

wire [7:0] r5_out;
ral_reg_r4_rtl r5(clk, rstn, hst_wdat[7:0],
r5_out, r5_sel, hst_wen,
r5_f1_in);

reg [7:0] _rdat;
unique_casez ({|r4_sel, |r5_sel})
2'b1?: _rdat = r4_out;
2'b?1: _rdat = r5_out;
2'b00: _rdat = 8'b0;

Register files are typically used as register file arrays. A simple register file will be
generated as if it were a register file array of size 1.
Register File Arrays
Register file arrays are implemented in a fashion similar to register arrays.
This section consists of the following subsections:
• Example
block b5 {
regfile rf[256] {
register r4;
register r4=r5;
}
}
interface ral_blk_b5_itf();

logic [7:0] r4_f1_in[256];
logic [7:0] r5_f1_in[256];

modport regs(input r4_f1_in,
input r5_f1_in);

modport usr(output r4_f1_in,
output r5_f1_in);

reg [7:0] _rf_sel_i;
reg rf_sel[256];
reg [31:0] i;
hst.ack = 0;

_rf_sel_i = 'bx;
for (i = 0; i < 256; i = i + 1) begin
rf_sel[i] = 'b0;
if (hst.adr == 0 + i*1) begin
rf_sel[i] = hst.sel[0];
_rf_sel_i = i;
end
end
end

wire [7:0] rf_out[256];
genvar _rf_i;
generate for (_rf_i=0; _rf_i<256; _rf_i=_rf_i+1)
begin: r1
ral_rfile_b5_rf_rtl i(hst.clk, hst.rstn, hst.adr - 0,
hst.wdat[7:0], rf_out[_rf_i],
rf_sel[_rf_i], hst.wen,
usr.r4_f1_in[_rf_i], usr.r5_f1_in[_rf_i]);
end
endgenerate

reg [7:0] _rdat;
begin: muxout
unique casez ({|rf_sel[_rf_sel_i]})
1'b1: _rdat = rf_out[_rf_sel_i];
1'b0: _rdat = 8'b0;
end
assign hst.rdat[7:0] = _rdat;

Systems
For every system definition, a module is generated. The module is named according to the
unique scoped system type name. A host-side slave interface for each domain is included
in the module pins. A host-side master interface is included for each module and sub-
system instantiated in the system.
The RTL generation template for a system is:
module ral_sys_<sysname>_rtl({<slave host-side interface>},
{<master host-side interface>});

<address decoding>
<readback muxing>

This section consists of the following subsections:
• Example
system s1 {
system s2 @'h1000 {
bytes 1
block b4;
}
block b1 @'h2000;
}
module ral_sys_s1_rtl(vmm_ral_host_itf.slave hst,
vmm_ral_host_itf.master s2,
vmm_ral_host_itf.master b1);

s2.sel[0] = 'b0;
b1.sel[1:0] = 'b0;
if (hst.adr >= 'h1000 && hst.adr <= 'h1000 + 255) begin
s2.sel[0] = hst.sel[0];
end
if (hst.adr >= 'h2000 && hst.adr <= 'h2000 + 7) begin
b1.sel[1] = hst.sel[0] & hst.adr[0];
b1.sel[0] = hst.sel[0] & ~hst.adr[0];
end
end

assign s2.adr = hst.adr - 'h1000;
assign s2.wdat = hst.wdat;
assign s2.wen = hst.wen;

assign b1.adr = (hst.adr - 'h2000) >> 1;
assign b1.wdat = {hst.wdat[7:0], hst.wdat[7:0]};
assign b1.wen = hst.wen;

reg [7:0] _rdat;
begin: muxout
unique casez ({s2.sel[0], b1.sel[1:0] })
3'b1??: begin
_rdat = s2.rdat;
hst.ack = s2.ack;
end
3'b?1?: begin

_rdat = b1.rdat[15:8];
hst.ack = b1.ack;
end
3'b??1: begin
_rdat = b1.rdat[7:0];
hst.ack = b1.ack;
end
3'b000: begin
_rdat = 8'b0;
hst.ack = 0;
end
end
assign hst.rdat[7:0] = _rdat;

Unsupported RALF Constructs and Functionality
The following RALF constructs or RAL functionality are explicitly not supported and will be
either ignored or a warning will be issued.
• Virtual registers
• Register files with a mix of shared and unshared registers
• Soft reset values
• Programmable base offset
• Programmable reset value

Appendix: RTL Implementation of RALF
Fields
Default implementation for fields, provided in $VCS_HOME/etc/rvm/shared/lib/RTL:
File vmm_ral_host_itf.v:
interface vmm_ral_host_itf(input bit clk,
input bit rstn);
logic [`VMM_RAL_ADDR_WIDTH-1:0] adr;
logic [`VMM_RAL_ADDR_BYTES-1:0] sel;
logic [`VMM_RAL_DATA_WIDTH-1:0] rdat;
logic [`VMM_RAL_DATA_WIDTH-1:0] wdat;
logic wen;
