vmm_ral_field TXE, CTRL_TXE;
vmm_ral_field RXE, CTRL_RXE;
vmm_ral_field PAR, CTRL_PAR;
vmm_ral_field DTR, CTRL_DTR;
vmm_ral_field CTS, CTRL_CTS;

ral_mem_tx_bfr tx_bfr;

endclass: ral_block_uart
