class ral_regfile_b1_rf;
ral_reg_b1_rf_r1 r1;
vmm_ral_field r1_f1;

ral_reg_b1_rf_r2 r2[4];
vmm_ral_field f2_f1[4];

endclass: ral_regfile_b1_rf

