vmm_mam::reconfigure()
function vmm_mam_cfg reconfigure(vmm_mam_cfg cfg = null);
function vmm_mam_cfg reconfigure(vmm_mam_cfg cfg = null);
Optionally modify the maximum and minimum addresses of the address space managed
by the allocation manager, allocation mode, or locality. The number of bytes per memory
location cannot be modified once an allocation manager has been constructed.
Returns the previous configuration.
All currently allocated regions must fall within the new address space.
Example 130
class ral_mam_cfg extends vmm_mam_cfg;
constraint mam_cfg_const {
end_offset == 64'h7f;
n_bytes == 8;
}

ral_mam_cfg mam_cfg;

if(!this.mam_cfg.randomize() with {start_offset ==
`START_OFFSET_A;})
`vmm_fatal(log,$psprintf("Failed to randomize RAL
mem cfg for %0h", `START_OFFSET_A));
end

if(!this.mam_cfg.randomize() with {start_offset ==
`START_OFFSET_B;})
`vmm_fatal(log,$psprintf("Failed to randomize

RAL mem cfg for %0h", `START_OFFSET_B));
end
mam_cfg = mam.reconfigure(this.mam_cfg);

endfunction : build
vmm_mam::reserve_region()
Reserve a specific memory region.
function vmm_mam_region reserve_region(bit [63:0] start_offset,
int unsigned n_bytes);
function vmm_mam_region reserve_region(bit [63:0] start_offset,
integer n_bytes);
Reserve a memory buffer of the specified number of bytes starting at the specified offset in
the memory. A descriptor of the reserved region is returned. If the specified region cannot
be reserved, null is returned.
It may not be possible to reserve a region because it overlaps with an already-allocated
region or it lies outside the address range managed by the memory manager.
Example 131

mam_region =
mam.reserve_region(mam_cfg.start_offset,mam_cfg.n_bytes);
if(mam_region == null)
`vmm_fatal(log,$psprintf({"Failed to reserve Memory
Location from ","%0h location."},
mam_cfg.start_offset));
end

vmm_mam::request_region()
Request a memory region.
function vmm_mam_region request_region(
int unsigned n_bytes, vmm_mam_allocator alloc = null);
function vmm_mam_region request_region(integer n_bytes,
vmm_mam_allocator alloct = null);
Request and reserve a memory buffer of the specified number of bytes starting at a
random location in the memory. If an allocator is specified, it is randomized to determine
the start offset of the region. If no allocator is specified, the allocator found in the
“vmm_mam::default_alloc” class property is randomized.
A descriptor of the allocated region is returned. If no region can be allocated, null is
returned. It may not be possible to allocate a region because there is no area in the
memory with enough consecutive locations to meet the size requirements or because
there is another contradiction when randomizing the allocator.
If the memory allocation is configured to vmm_mam::THRIFTY or vmm_mam::NEARBY (see
the “vmm_mam_cfg::mode” and “vmm_mam_cfg::locality” class properties, respectively),
a suitable region is first sought procedurally. If no suitable region is found, then the
allocator is randomized. The allocator is immediately randomized when the memory
allocation is configured as vmm_mam::BROADand vmm_mam::GREEDY.
The default value of vmm_mam_cfg::locality is BROAD and the default value of
vmm_mam_cfg::mode is THRIFTY. However, the NEARBY and GREEDY modes are
not implemented.
Example 132
program test_regions;

ral_mam_cfg mam_cfg;
vmm_mam_region mam_reg;

mam_reg = mam.request_region(mam_cfg.n_bytes);

if(mam_reg == null)
`vmm_fatal(log,$psprintf("Failed to request Memory
Location for %d bytes.", mam_cfg.n_bytes));
end

end

vmm_mam::release_region()
Release a previously allocated memory region.
function void release_region(vmm_mam_region region);
task release_region(vmm_mam_region region);
Release the specified previously allocated memory region. An error is issued if the
specified region has not been previously allocated or is no longer allocated.
Example 133

ral_mam_cfg ral_mam_cfg_inst,mam_cfg;
vmm_mam_region mam_reg;

mam = new("RAL memory manager",ral_mam_cfg_inst,mem);
mam_reg = mam.request_region(256);

//Releasing a region before next reconfiguration and
//read/write operations
mam.release_region(mam_reg);
if(!this.ral_mam_cfg_inst.randomize() with
{start_offset == `START_OFFSET_A;})
mam_cfg = mam.reconfigure(ral_mam_cfg_inst);
mam_reg = mam.request_region(256);

end
