rand vmm_ral_field my_field_2;

function new();
super.new();
//Here vmm_ral::A1 is value for the access_e enum. You can change
it
//to get the required value for particular field.
this.my_field_1 = new(this, "my_field_1", 1, vmm_ral::RW, );
this.my_field_1 = new(this, "my_field_1", 1, vmm_ral::A1, );

this.ral_model.my_reg.my_field_1.write(status,data,vmm_ral::BACKDOOR);
`vmm_note(log,$psprintf(" Written Value:: %0h with status %0s",
data,status.name);
written = 1'b1;
end
wait(written);
this.ral_model.my_reg.my_field_1.read(status,rd_data);
`vmm_note(log,$psprintf("my_field_1 Value:: %0h with status %0s",
rd_data,status.name);

this.ral_model.my_reg.my_field_2.read(status,rd_data);
`vmm_note(log,$psprintf("my_field_2 Value:: %0h with status %0s",
rd_data,status.name);
written = 1'b0;
end

vmm_ral_field::peek()
Peek a field value from the design.
virtual task peek(

virtual function vmm_rw::status_e peek_t(
Peek the current value of the field from the design using a backdoor access. The value of
the field in the design is not modified, regardless of the access mode.
The optional value of the data_id, scenario_id and stream_idarguments are passed to
the backdoor access method. This allows the physical and backdoor read accesses to be
traced back to the higher-level transaction which caused the access to occur.
The mirrored value of the field, and all other fields located in the same register, is updated
with the value peeked from the design.
Example 258
vmm_ral_block b;
bit [63:0] value;
b.register.fld.peek(status,value);
`vmm_note(log, $psprintf("b.register.fld %h", value));
end
vmm_ral_field::poke()
Poke a field value in the design.
virtual task poke(
virtual function vmm_rw::status_e poke_t(

Deposit the specified field value in the design using a backdoor access. The value of the
field is updated, regardless of the access mode.
accesses to be traced back to the higher-level transaction that caused the access to occur.
If the register, where this field is physically located, contains other fields, the current value
of the other fields are peeked first then poked back in.
Example 259
vmm_ral_block b;
b.register.fld.poke(status, 8'hAB);
if (status != vmm_rw::IS_OK) begin
`vmm_error(log, $psprintf("Update status was %s", status.name()));
end
vmm_ral_field::mirror()
Updates the mirrored value of this field to match the design.
virtual task mirror(
input vmm_ral::check_e check = vmm_ral::QUIET,
input vmm_ral::path_e path = vmm_ral::DEFAULT,
input string domain = "")
virtual function vmm_rw::status_e mirror_t(
vmm_ral::check_e check = vmm_ral::QUIET,
vmm_ral::path_e path = vmm_ral::DEFAULT,
string domain = "")
Updates the content of the field mirror value for all the fields in the same register to match
the current values in the design. The mirroring can be performed using the physical
interfaces (frontdoor) or “vmm_ral_field::peek()” (backdoor). If the check argument is

specified as vmm_ral::VERB, an error message is issued if the current mirrored value of
the entire register does not match the actual value in the design.
The content of a write-only field is mirrored and optionally checked only if a
vmm_ral::BACKDOOR access path is used to read the register containing the field.
If the field is located in a register shared by more than one physical interface, a domain
must be specified if a physical access is used (front-door access).
Example 260

this.ral_model.my_reg.my_field.set(data);
this.ral_model.my_reg.my_field.mirror(status);
`vmm_note(log,$psprintf(" Mirrored Value:: %0h with status %0s",
data,status.name);
mirrored = 1'b1;
end

vmm_ral_field::append_callback()
function void append_callback(vmm_ral_field callbacks cbs)
task append_callback(vmm_ral_field_callbacks cbs)
Appends the specified callback extension instance to the registered callbacks for this field
descriptor. Callbacks are invoked in the order of registration.
Note that field callback methods will be invoked before their corresponding “vmm_ral_reg”
callback methods.
Example 261

my_ral_field_callbacks cb;

env.ral_model.my_field.prepend_callback(cb);

end

