"1101", "HALT",
0,0
};
main(int argc, char *argv[])
{
char inbuff[1024];
int index;
long n;

}

while (1)
{
clearerr(stdin);
if (fgets(inbuff, 1024, stdin) == (char*) 0) break;
n = strlen(inbuff);
if (n > 0)
{
inbuff[n] = '\0';
if (inbuff[n-1] == '\n') inbuff[n-1] = '\0';
if (strcmp(inbuff, "exit") ==0) return 0;
index =0;
while(alias_table[index].number != 0)
{
