//
// __TBTraversal()
//
fsdbRC
__TBTraversal(void)
{
ffwObject
*ffw_obj = NULL;
*ffr_obj = NULL;
char
fname[] = "tb_trvs.fsdb";
fsdbRC
rc = FSDB_RC_SUCCESS;
fsdbXTag
start_xtag, close_xtag;
//
// Write to the FSDB file
//
__OpenFsdbFileForWrite(&ffw_obj, fname, FSDB_FT_VERILOG);

ffw_SetGlitchNum(ffw_obj, 0);
//
// Turn on sequence number if necessary. Sequence number affects the
// order of value change returned.
//
ffw_DumpSeqNumTurnOn(ffw_obj);
__CreateTree(ffw_obj);
__CreateVC(ffw_obj);
ffw_Close(ffw_obj);
//
// Open the FSDB file for read
//
rc = __OpenFsdbFileForRead(&ffr_obj, fname);
if (rc != FSDB_RC_SUCCESS) {
fprintf(stderr, "Fsdb file(%s) failed to be opened for read.\n",
fname);
assert(FALSE);
}
//
// Set view window if necessary. Only value changes within the view
window
// is returned.
//
start_xtag.hltag.H = 0;
start_xtag.hltag.L = 600;
close_xtag.hltag.H = 0;
close_xtag.hltag.L = 800;
ffr_obj->ffrSetViewWindow(&start_xtag, &close_xtag);
//
// Traverse the vc in the FSDB file
//
rc = __TraverseVC(ffr_obj);
fprintf(stdout, "Time-based traversal done!!.\n");
ffr_obj->ffrClose();
}

return rc;

